def list_workspaces(limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0524000" if __import__("os").path.isdir("./environment_mix/0524000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_workspaces"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        if not s:
            return None
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_str, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status_str,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta:
            row.update(meta)
        logs.append(row)
        _save("request_logs.json", logs)

    # rate/quota enforcement (if config present, otherwise defaults)
    def _enforce_limits():
        cfg = _load("service_limits.json")
        if isinstance(cfg, list) and cfg:
            cfg = cfg[0]
        if not isinstance(cfg, dict):
            cfg = {}
        rl = cfg.get("rate_limit", {}) if isinstance(cfg.get("rate_limit", {}), dict) else {}
        qt = cfg.get("quota", {}) if isinstance(cfg.get("quota", {}), dict) else {}
        rpm = rl.get("requests_per_minute", 120)
        rpd = qt.get("requests_per_day", 20000)
        if not isinstance(rpm, int) or rpm <= 0:
            rpm = 120
        if not isinstance(rpd, int) or rpd <= 0:
            rpd = 20000

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        win_min = now - datetime.timedelta(minutes=1)
        win_day = now - datetime.timedelta(days=1)

        cmin = 0
        cday = 0
        for r in logs:
            ts = _parse_iso(r.get("timestamp"))
            if not ts:
                continue
            if ts >= win_min:
                cmin += 1
            if ts >= win_day:
                cday += 1

        if cmin >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if cday >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    # validate limit
    if limit is None:
        limit_i = 25
    elif not isinstance(limit, int):
        err = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
        _log("VALIDATION_ERROR", error=err["error"])
        return err
    else:
        limit_i = limit
    if limit_i < 1 or limit_i > 100:
        err = _err("VALIDATION_ERROR", "limit must be between 1 and 100.", field="limit")
        _log("VALIDATION_ERROR", error=err["error"])
        return err

    # cursor is "opaque token representing last returned workspace.slug"
    # Accept:
    # - our own base64(json {"last_slug": ...})
    # - OR any string; if it doesn't decode, treat it as the last_slug directly (opaque passthrough)
    last_slug = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            err = _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")
            _log("VALIDATION_ERROR", error=err["error"])
            return err
        tok = cursor.strip()
        decoded = None
        pad = "=" * ((4 - (len(tok) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("last_slug"), str):
                decoded = obj.get("last_slug")
        except Exception:
            decoded = None
        last_slug = decoded if decoded is not None else tok

    lim_err = _enforce_limits()
    if lim_err:
        _log(lim_err["error"]["code"], error=lim_err["error"])
        return lim_err

    data = _load("workspaces.json")
    if isinstance(data, dict) and isinstance(data.get("rows"), list):
        rows = data["rows"]
    elif isinstance(data, list):
        rows = data
    else:
        rows = []

    # list ordered by slug; include all rows (Bitbucket "accessible") regardless of archived/revoked for listing
    items = [r for r in rows if isinstance(r, dict) and isinstance(r.get("slug"), str)]
    items.sort(key=lambda r: (r.get("slug") or "").lower())

    start_idx = 0
    if last_slug is not None:
        # start after last_slug in ordering
        for i, r in enumerate(items):
            if (r.get("slug") or "") == last_slug:
                start_idx = i + 1
                break
        else:
            # token might not match exactly (opaque from upstream). Don't error: start from beginning.
            start_idx = 0

    page = items[start_idx:start_idx + limit_i]
    has_more = (start_idx + limit_i) < len(items)
    next_cursor = None
    if has_more and page:
        payload = json.dumps({"last_slug": page[-1].get("slug")}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    resp = {
        "values": page,
        "limit": limit_i,
        "cursor": next_cursor,
        "has_more": has_more,
        "total": len(items),
    }
    _log("ok", limit=limit_i, cursor_in=cursor, cursor_out=next_cursor, returned=len(page), total=len(items))
    return resp

def get_workspace(workspaceSlug, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0524000" if __import__("os").path.isdir("./environment_mix/0524000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    start = time.time()
    ts = _now_iso()

    if not isinstance(workspaceSlug, str) or not workspaceSlug.strip():
        return _err("VALIDATION_ERROR", "workspaceSlug must be a non-empty string.")

    slug = workspaceSlug.strip()

    workspaces = _load("workspaces.json")
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("slug") == slug:
            ws = w
            break

    if ws is None:
        # Log
        for log_name in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, log_name)):
                logs = _load(log_name)
                if not isinstance(logs, list):
                    logs = []
                logs.append(
                    {
                        "id": f"req_{int(time.time()*1000)}",
                        "endpoint": "get_workspace",
                        "status": "not_found",
                        "timestamp": ts,
                        "latency_ms": int((time.time() - start) * 1000),
                    }
                )
                _save(log_name, logs)
                break
        return _err("NOT_FOUND", "Workspace not found.")

    if ws.get("status") == "revoked":
        for log_name in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, log_name)):
                logs = _load(log_name)
                if not isinstance(logs, list):
                    logs = []
                logs.append(
                    {
                        "id": f"req_{int(time.time()*1000)}",
                        "endpoint": "get_workspace",
                        "status": "not_found",
                        "timestamp": ts,
                        "latency_ms": int((time.time() - start) * 1000),
                    }
                )
                _save(log_name, logs)
                break
        return _err("NOT_FOUND", "Workspace not found.")

    # Log success
    for log_name in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
        if os.path.exists(os.path.join(_DB, log_name)):
            logs = _load(log_name)
            if not isinstance(logs, list):
                logs = []
            logs.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": "get_workspace",
                    "status": "succeeded",
                    "timestamp": ts,
                    "latency_ms": int((time.time() - start) * 1000),
                }
            )
            _save(log_name, logs)
            break

    return {"workspace": ws}

def list_repositories(workspaceSlug, query=None, sort=None, role=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0524000" if __import__("os").path.isdir("./environment_mix/0524000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if not v:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1]
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _encode_cursor(last_key):
        payload = json.dumps({"last": last_key}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _decode_cursor(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or not tok.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
        t = tok.strip()
        pad = "=" * ((4 - (len(t) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((t + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "cursor is not a valid pagination token.")
        if not isinstance(obj, dict) or "last" not in obj:
            return _err("VALIDATION_ERROR", "cursor is not a valid pagination token.")
        return obj["last"]

    start = time.time()
    ts = _now_iso()

    if not isinstance(workspaceSlug, str) or not workspaceSlug.strip():
        return _err("VALIDATION_ERROR", "workspaceSlug must be a non-empty string.")
    wslug = workspaceSlug.strip()

    # Validate limit
    if limit is None:
        limit_i = 25
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100.")
        limit_i = limit

    # Validate sort
    sort_field = None
    sort_desc = False
    if sort is not None:
        if not isinstance(sort, str) or not sort.strip():
            return _err("VALIDATION_ERROR", "sort must be a non-empty string when provided.")
        s = sort.strip()
        if s.startswith("-"):
            sort_desc = True
            s = s[1:]
        if s not in ("name", "created_on", "updated_on"):
            return _err("VALIDATION_ERROR", "sort must be one of name, created_on, updated_on (optionally prefixed by '-').")
        sort_field = s

    # Validate query
    if query is not None and (not isinstance(query, str)):
        return _err("VALIDATION_ERROR", "query must be a string when provided.")

    # Validate role (cannot enforce upstream permissions; accept string, filter if repo row contains role metadata)
    if role is not None and (not isinstance(role, str) or not role.strip()):
        return _err("VALIDATION_ERROR", "role must be a non-empty string when provided.")
    role_v = role.strip().lower() if isinstance(role, str) and role.strip() else None

    # Validate cursor
    last = None
    if cursor is not None:
        decoded = _decode_cursor(cursor)
        if isinstance(decoded, dict) and "error" in decoded:
            return decoded
        last = decoded

    # Resolve workspace
    workspaces = _load("workspaces.json")
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("slug") == wslug and w.get("status") != "revoked":
            ws = w
            break
    if ws is None:
        # Log
        for log_name in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, log_name)):
                logs = _load(log_name)
                if not isinstance(logs, list):
                    logs = []
                logs.append(
                    {
                        "id": f"req_{int(time.time()*1000)}",
                        "endpoint": "list_repositories",
                        "status": "not_found",
                        "timestamp": ts,
                        "latency_ms": int((time.time() - start) * 1000),
                    }
                )
                _save(log_name, logs)
                break
        return _err("NOT_FOUND", "Workspace not found.")

    repos = _load("repositories.json")
    rows = [r for r in repos if isinstance(r, dict) and r.get("workspace_id") == ws.get("id") and r.get("status") == "active"]

    # Optional role filtering if stored on repo row
    if role_v is not None:
        def _role_match(r):
            # Common patterns: r["role"], r["permission"], r["access_role"]
            for k in ("role", "permission", "access_role"):
                v = r.get(k)
                if isinstance(v, str) and v.strip().lower() == role_v:
                    return True
            # If role isn't stored, we cannot safely infer; in a real integration this would be enforced upstream.
            return False

        rows = [r for r in rows if _role_match(r)]

    # Query filter (case-insensitive substring match on name/description)
    if isinstance(query, str) and query.strip():
        q = query.strip().lower()

        def _match(r):
            n = (r.get("name") or "")
            d = (r.get("description") or "")
            return (isinstance(n, str) and q in n.lower()) or (isinstance(d, str) and q in d.lower())

        rows = [r for r in rows if _match(r)]

    # Sorting
    if sort_field is None:
        # Default stable sort by name then slug
        rows.sort(key=lambda r: (str(r.get("name", "")).lower(), str(r.get("slug", "")).lower(), str(r.get("id", ""))))
    else:
        if sort_field == "name":
            keyfn = lambda r: (str(r.get("name", "")).lower(), str(r.get("slug", "")).lower(), str(r.get("id", "")))
        elif sort_field == "created_on":
            keyfn = lambda r: (_parse_dt(r.get("created_on")) or datetime.datetime.min, str(r.get("id", "")))
        else:  # updated_on
            keyfn = lambda r: (_parse_dt(r.get("updated_on")) or datetime.datetime.min, str(r.get("id", "")))
        rows.sort(key=keyfn, reverse=sort_desc)

    # Pagination by last seen repo slug within current ordering: cursor stores opaque "last" key as dict
    if last is not None:
        # Expect last to be a dict with fields we set
        if not isinstance(last, dict) or "id" not in last:
            return _err("VALIDATION_ERROR", "cursor is not a valid pagination token.")
        last_id = last.get("id")

        # Find index of last_id in current ordering; start after it
        idx = -1
        for i, r in enumerate(rows):
            if r.get("id") == last_id:
                idx = i
                break
        if idx >= 0:
            rows = rows[idx + 1 :]
        else:
            # If not found, treat as invalid cursor (since it doesn't represent last returned item for these filters)
            return _err("VALIDATION_ERROR", "cursor does not match the current result set.")

    page = rows[:limit_i]
    has_more = len(rows) > len(page)
    next_cursor = _encode_cursor({"id": page[-1].get("id")}) if (has_more and page) else None

    # Log
    for log_name in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
        if os.path.exists(os.path.join(_DB, log_name)):
            logs = _load(log_name)
            if not isinstance(logs, list):
                logs = []
            logs.append(
                {
                    "id": f"req_{int(time.time()*1000)}",
                    "endpoint": "list_repositories",
                    "status": "succeeded",
                    "timestamp": ts,
                    "latency_ms": int((time.time() - start) * 1000),
                }
            )
            _save(log_name, logs)
            break

    return {
        "values": page,
        "page": {"limit": limit_i, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more},
        "workspace": {"id": ws.get("id"), "slug": ws.get("slug"), "name": ws.get("name")},
    }

def get_repository(workspaceSlug, repoSlug, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0524000" if __import__("os").path.isdir("./environment_mix/0524000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_repository"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _load_limits():
        cfg = _load("service_limits.json")
        if isinstance(cfg, list) and cfg:
            cfg = cfg[0]
        if not isinstance(cfg, dict):
            cfg = {}
        rl = cfg.get("rate_limit") if isinstance(cfg.get("rate_limit"), dict) else {}
        qt = cfg.get("quota") if isinstance(cfg.get("quota"), dict) else {}
        rpm = rl.get("requests_per_minute", 120)
        rpd = qt.get("requests_per_day", 20000)
        if not isinstance(rpm, int) or rpm <= 0:
            rpm = 120
        if not isinstance(rpd, int) or rpd <= 0:
            rpd = 20000
        return rpm, rpd

    def _check_limits():
        rpm, rpd = _load_limits()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        win_min = now - datetime.timedelta(minutes=1)
        win_day = now - datetime.timedelta(days=1)
        cmin = 0
        cday = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= win_min:
                cmin += 1
            if ts >= win_day:
                cday += 1
        if cmin >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        if cday >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=rpd, window_seconds=86400)
        return None

    def _log(status, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta:
            row.update(meta)
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(workspaceSlug, str) or not workspaceSlug.strip():
            e = _err("VALIDATION_ERROR", "workspaceSlug must be a non-empty string", workspaceSlug=workspaceSlug)
            _log("error", error=e["error"])
            return e
        if not isinstance(repoSlug, str) or not repoSlug.strip():
            e = _err("VALIDATION_ERROR", "repoSlug must be a non-empty string", repoSlug=repoSlug)
            _log("error", error=e["error"])
            return e

        limerr = _check_limits()
        if limerr:
            _log("error", error=limerr["error"])
            return limerr

        workspaces = _load("workspaces.json")
        if isinstance(workspaces, dict) and "rows" in workspaces and isinstance(workspaces["rows"], list):
            workspaces = workspaces["rows"]
        if not isinstance(workspaces, list):
            workspaces = []

        ws = None
        for w in workspaces:
            if isinstance(w, dict) and w.get("slug") == workspaceSlug:
                ws = w
                break
        if not ws or ws.get("status") == "revoked":
            e = _err("NOT_FOUND", "Workspace not found", workspaceSlug=workspaceSlug)
            _log("error", error=e["error"])
            return e

        repos = _load("repositories.json")
        if isinstance(repos, dict) and "rows" in repos and isinstance(repos["rows"], list):
            repos = repos["rows"]
        if not isinstance(repos, list):
            repos = []

        repo = None
        for r in repos:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") == ws.get("id") and r.get("slug") == repoSlug:
                repo = r
                break

        if not repo or repo.get("status") == "deleted":
            # As per business rule: status must not be 'deleted'
            e = _err("NOT_FOUND", "Repository not found", workspaceSlug=workspaceSlug, repoSlug=repoSlug)
            _log("error", error=e["error"])
            return e

        out = {"repository": repo}
        _log("ok", workspace_id=ws.get("id"), repository_id=repo.get("id"))
        return out
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error", detail=str(ex))
        _log("error", error=e["error"])
        return e

