            row.update(meta)
        logs.append(row)
        _save("request_logs.json", logs)

    def _encode_cursor(last_key):
        payload = {"k": last_key}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", cursor=cur)
        s = cur.strip()
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid", cursor=cur)
        if not isinstance(obj, dict) or "k" not in obj:
            return _err("VALIDATION_ERROR", "cursor is invalid", cursor=cur)
        return obj.get("k")

