            e = _err("VALIDATION_ERROR", "state must be one of OPEN, MERGED, DECLINED, SUPERSEDED", state=state)
            _log("error", error=e["error"])
            return e
        if query is not None and not isinstance(query, str):
            e = _err("VALIDATION_ERROR", "query must be a string when provided", query=query)
            _log("error", error=e["error"])
            return e

        if limit is None:
            limit_i = 25
        else:
            if not isinstance(limit, int):
                e = _err("VALIDATION_ERROR", "limit must be an integer", limit=limit)
                _log("error", error=e["error"])
                return e
            if limit < 1 or limit > 100:
                e = _err("VALIDATION_ERROR", "limit must be between 1 and 100", limit=limit)
                _log("error", error=e["error"])
                return e
            limit_i = limit

        limerr = _check_limits()
        if limerr:
            _log("error", error=limerr["error"])
            return limerr

        workspaces = _load("workspaces.json")
        if isinstance(workspaces, dict) and "rows" in workspaces and isinstance(workspaces["rows"], list):
            workspaces = workspaces["rows"]
        if not isinstance(workspaces, list):
            workspaces = []

        ws = None
        for w in workspaces:
            if isinstance(w, dict) and w.get("slug") == workspaceSlug:
                ws = w
                break
        if not ws or ws.get("status") == "revoked":
            e = _err("NOT_FOUND", "Workspace not found", workspaceSlug=workspaceSlug)
            _log("error", error=e["error"])
            return e

        repos = _load("repositories.json")
        if isinstance(repos, dict) and "rows" in repos and isinstance(repos["rows"], list):
            repos = repos["rows"]
        if not isinstance(repos, list):
            repos = []

        repo = None
        for r in repos:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") == ws.get("id") and r.get("slug") == repoSlug:
                repo = r
                break
        if not repo or repo.get("status") == "deleted":
            e = _err("NOT_FOUND", "Repository not found", workspaceSlug=workspaceSlug, repoSlug=repoSlug)
            _log("error", error=e["error"])
            return e

        cur_key = _decode_cursor(cursor)
        if isinstance(cur_key, dict) and "error" in cur_key:
            _log("error", error=cur_key["error"])
            return cur_key

        prs = _load("pull_requests.json")
        if isinstance(prs, dict) and "rows" in prs and isinstance(prs["rows"], list):
            prs = prs["rows"]
        if not isinstance(prs, list):
            prs = []

        items = []
        ql = query.lower() if isinstance(query, str) and query else None
        for pr in prs:
            if not isinstance(pr, dict):
                continue
            if pr.get("repository_id") != repo.get("id"):
                continue
            # Local record lifecycle: ignore deleted records
            if pr.get("status") == "deleted":
                continue
            if state is not None and pr.get("state") != state:
                continue
            if ql:
                hay = " ".join([
                    str(pr.get("title") or ""),
                    str(pr.get("description") or ""),
                    str(pr.get("author_display_name") or ""),
                ]).lower()
                if ql not in hay:
                    continue
            items.append(pr)

        # Stable ordering: by updated_on desc then bb_pr_id desc then id
        def _sort_key(pr):
            u = _parse_dt(pr.get("updated_on")) or _parse_dt(pr.get("created_on")) or datetime.datetime(1970, 1, 1)
            bbid = pr.get("bb_pr_id")
            try:
                bbid = int(bbid)
            except Exception:
                bbid = 0
            return (-int(u.timestamp()), -bbid, str(pr.get("id") or ""))

        items.sort(key=_sort_key)

        # cursor is last returned composite key based on bb_pr_id and id
        def _cursor_key(pr):
            bbid = pr.get("bb_pr_id")
            try:
                bbid = int(bbid)
            except Exception:
                bbid = 0
            return f"{bbid}:{pr.get('id') or ''}"

        start_idx = 0
        if cur_key is not None:
            # cur_key is the last returned key; start after it
            for i, pr in enumerate(items):
                if _cursor_key(pr) == cur_key:
                    start_idx = i + 1
                    break

        page = items[start_idx:start_idx + limit_i]
        has_more = start_idx + limit_i < len(items)
        next_cursor = _encode_cursor(_cursor_key(page[-1])) if has_more and page else None

        out = {
            "pull_requests": page,
            "meta": {
                "total": len(items),
                "limit": limit_i,
                "has_more": bool(has_more),
                "next_cursor": next_cursor,
            },
        }
        _log("ok", workspace_id=ws.get("id"), repository_id=repo.get("id"))
        return out
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error", detail=str(ex))
        _log("error", error=e["error"])
        return e

