def add_pr_comment(workspaceSlug, repoSlug, prId, content, inline=None, **_extra):
    import json, os, datetime, time, uuid, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0524000" if __import__("os").path.isdir("./environment_mix/0524000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "add_pr_comment"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _load_limits():
        cfg = _load("service_limits.json")
        if isinstance(cfg, list) and cfg:
            cfg = cfg[0]
        if not isinstance(cfg, dict):
            cfg = {}
        rl = cfg.get("rate_limit") if isinstance(cfg.get("rate_limit"), dict) else {}
        qt = cfg.get("quota") if isinstance(cfg.get("quota"), dict) else {}
        rpm = rl.get("requests_per_minute", 120)
        rpd = qt.get("requests_per_day", 20000)
        if not isinstance(rpm, int) or rpm <= 0:
            rpm = 120
        if not isinstance(rpd, int) or rpd <= 0:
            rpd = 20000
        return rpm, rpd

    def _check_limits():
        rpm, rpd = _load_limits()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        win_min = now - datetime.timedelta(minutes=1)
        win_day = now - datetime.timedelta(days=1)
        cmin = 0
        cday = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= win_min:
                cmin += 1
            if ts >= win_day:
                cday += 1
        if cmin >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        if cday >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=rpd, window_seconds=86400)
        return None

    def _log(status, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta:
            row.update(meta)
        logs.append(row)
        _save("request_logs.json", logs)

    def _new_id(prefix, existing_ids):
        # ULID-like time component + random
        ts = int(time.time() * 1000)
        rnd = uuid.uuid4().hex[:10]
        candidate = f"{prefix}_{ts:x}{rnd}"
        if candidate not in existing_ids:
            return candidate
        for _ in range(10):
            candidate = f"{prefix}_{ts:x}{uuid.uuid4().hex[:12]}"
            if candidate not in existing_ids:
                return candidate
        return f"{prefix}_{uuid.uuid4().hex}"

    try:
        if not isinstance(workspaceSlug, str) or not workspaceSlug.strip():
            e = _err("VALIDATION_ERROR", "workspaceSlug must be a non-empty string", workspaceSlug=workspaceSlug)
            _log("error", error=e["error"])
            return e
        if not isinstance(repoSlug, str) or not repoSlug.strip():
            e = _err("VALIDATION_ERROR", "repoSlug must be a non-empty string", repoSlug=repoSlug)
            _log("error", error=e["error"])
            return e
        if not isinstance(prId, str) or not prId.strip():
            e = _err("VALIDATION_ERROR", "prId must be a non-empty string", prId=prId)
            _log("error", error=e["error"])
            return e
        if not isinstance(content, str) or len(content) < 1:
            e = _err("VALIDATION_ERROR", "content must be a non-empty string", content=content)
            _log("error", error=e["error"])
            return e

        # Inline validation: if provided, must have path and line and line > 0
        inline_path = None
        inline_line = None
        if inline is not None:
            if not isinstance(inline, dict):
                e = _err("VALIDATION_ERROR", "inline must be an object when provided", inline=inline)
                _log("error", error=e["error"])
                return e
            inline_path = inline.get("path")
            inline_line = inline.get("line")
            if not isinstance(inline_path, str) or not inline_path.strip():
                e = _err("VALIDATION_ERROR", "inline.path must be a non-empty string", inline=inline)
                _log("error", error=e["error"])
                return e
            if not isinstance(inline_line, int) or inline_line <= 0:
                e = _err("VALIDATION_ERROR", "inline.line must be a positive integer", inline=inline)
                _log("error", error=e["error"])
                return e

        # Parse prId as integer > 0 (business rule)
        try:
            pr_int = int(prId)
        except Exception:
            e = _err("VALIDATION_ERROR", "prId must parse as a positive integer", prId=prId)
            _log("error", error=e["error"])
            return e
        if pr_int <= 0:
            e = _err("VALIDATION_ERROR", "prId must be > 0", prId=prId)
            _log("error", error=e["error"])
            return e

        limerr = _check_limits()
        if limerr:
            _log("error", error=limerr["error"])
            return limerr

        workspaces = _load("workspaces.json")
        if isinstance(workspaces, dict) and "rows" in workspaces and isinstance(workspaces["rows"], list):
            workspaces = workspaces["rows"]
        if not isinstance(workspaces, list):
            workspaces = []

        ws = None
        for w in workspaces:
            if isinstance(w, dict) and w.get("slug") == workspaceSlug:
                ws = w
                break
        if not ws or ws.get("status") == "revoked":
            e = _err("NOT_FOUND", "Workspace not found", workspaceSlug=workspaceSlug)
            _log("error", error=e["error"])
            return e

        repos = _load("repositories.json")
        if isinstance(repos, dict) and "rows" in repos and isinstance(repos["rows"], list):
            repos = repos["rows"]
        if not isinstance(repos, list):
            repos = []

        repo = None
        for r in repos:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") == ws.get("id") and r.get("slug") == repoSlug:
                repo = r
                break
        if not repo or repo.get("status") == "deleted":
            e = _err("NOT_FOUND", "Repository not found", workspaceSlug=workspaceSlug, repoSlug=repoSlug)
            _log("error", error=e["error"])
            return e

        prs = _load("pull_requests.json")
        if isinstance(prs, dict) and "rows" in prs and isinstance(prs["rows"], list):
            prs = prs["rows"]
        if not isinstance(prs, list):
            prs = []

        pr_row = None
        for pr in prs:
            if not isinstance(pr, dict):
                continue
            if pr.get("repository_id") == repo.get("id") and pr.get("bb_pr_id") == pr_int and pr.get("status") != "deleted":
                pr_row = pr
                break
        if not pr_row:
            e = _err("NOT_FOUND", "Pull request not found", workspaceSlug=workspaceSlug, repoSlug=repoSlug, prId=prId)
            _log("error", error=e["error"])
            return e

        comments = _load("pull_request_comments.json")
        if isinstance(comments, dict) and "rows" in comments and isinstance(comments["rows"], list):
            comments = comments["rows"]
        if not isinstance(comments, list):
            comments = []

        existing_ids = set()
        existing_bb_ids = set()
        for c in comments:
            if not isinstance(c, dict):
                continue
            cid = c.get("id")
            if isinstance(cid, str):
                existing_ids.add(cid)
            # uniqueness: (pull_request_id, bb_comment_id) when bb_comment_id not null
            if c.get("pull_request_id") == pr_row.get("id") and c.get("bb_comment_id") is not None:
                try:
                    existing_bb_ids.add(int(c.get("bb_comment_id")))
                except Exception:
                    pass

        # Simulate upstream write-through by generating a bb_comment_id not colliding within PR
        bb_comment_id = None
        # If there are upstream ids, increment max; else random positive
        if existing_bb_ids:
            bb_comment_id = max(existing_bb_ids) + 1
        else:
            bb_comment_id = random.randint(1, 10_000_000)
            # avoid collision just in case
            while bb_comment_id in existing_bb_ids:
                bb_comment_id = random.randint(1, 10_000_000)

        now_iso = _now_iso()
        new_row = {
            "id": _new_id("bb_prc", existing_ids),
            "pull_request_id": pr_row.get("id"),
            "bb_comment_id": int(bb_comment_id),
            "content": content,
            "author_display_name": None,
            "author_account_id": None,
            "inline_path": inline_path.strip() if isinstance(inline_path, str) else None,
            "inline_line": int(inline_line) if isinstance(inline_line, int) else None,
            "links": None,
            "status": "active",
            "created_on": now_iso,
            "updated_on": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }

        comments.append(new_row)
        _save("pull_request_comments.json", comments)

        out = {"comment": new_row}
        _log("ok", workspace_id=ws.get("id"), repository_id=repo.get("id"), pull_request_id=pr_row.get("id"), comment_id=new_row.get("id"))
        return out
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error", detail=str(ex))
        _log("error", error=e["error"])
        return e

