def search(workspaceSlug, repoSlug=None, query=None, scope=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0524000" if __import__("os").path.isdir("./environment_mix/0524000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _ensure_logs():
        try:
            with open(os.path.join(_DB, "request_logs.json"), encoding="utf-8") as f:
                d = json.load(f)
                if isinstance(d, list):
                    return d
        except Exception:
            return []
        return []

    def _save_logs(logs):
        _save("request_logs.json", logs)

    def _rate_check_and_log(endpoint, status, latency_ms, meta=None):
        logs = _ensure_logs()
        now_ts = _now()
        # Basic rate limit: 120 requests / rolling minute
        window_sec = 60
        limit_per_min = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_sec)
        cnt = 0
        for r in logs:
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if dt.replace(tzinfo=None) >= cutoff:
                    cnt += 1
        if cnt >= limit_per_min:
            logs.append(
                {
                    "id": _new_id("req"),
                    "timestamp": now_ts,
                    "endpoint": endpoint,
                    "status": "RATE_LIMIT",
                    "latency_ms": latency_ms,
                    "meta": meta or {},
                }
            )
            _save_logs(logs)
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=limit_per_min)
        logs.append(
            {
                "id": _new_id("req"),
                "timestamp": now_ts,
                "endpoint": endpoint,
                "status": status,
                "latency_ms": latency_ms,
                "meta": meta or {},
            }
        )
        _save_logs(logs)
        return None

    t0 = time.time()
    endpoint = "search"

    # Validate
    if not isinstance(workspaceSlug, str) or len(workspaceSlug) < 1:
        latency = int((time.time() - t0) * 1000)
        rl = _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "workspaceSlug"})
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "workspaceSlug must be a non-empty string.", field="workspaceSlug")

    if repoSlug is not None and (not isinstance(repoSlug, str) or len(repoSlug) < 1):
        latency = int((time.time() - t0) * 1000)
        rl = _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "repoSlug"})
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "repoSlug must be a non-empty string when provided.", field="repoSlug")

    if query is not None and not isinstance(query, str):
        latency = int((time.time() - t0) * 1000)
        rl = _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "query"})
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "query must be a string when provided.", field="query")

    if scope is None:
        scope = "all"
    if not isinstance(scope, str) or scope not in ("repositories", "pullrequests", "commits", "code", "all"):
        latency = int((time.time() - t0) * 1000)
        rl = _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "scope"})
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "Invalid scope.", field="scope", allowed=["repositories", "pullrequests", "commits", "code", "all"])

    if limit is None:
        limit_i = 25
    else:
        if not (isinstance(limit, int) or isinstance(limit, float)) or isinstance(limit, bool):
            latency = int((time.time() - t0) * 1000)
            rl = _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "limit"})
            if rl:
                return rl
            return _err("VALIDATION_ERROR", "limit must be a number between 1 and 100.", field="limit")
        limit_i = int(limit)
    if limit_i < 1 or limit_i > 100:
        latency = int((time.time() - t0) * 1000)
        rl = _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "limit"})
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100.", field="limit")

    # Scope-specific constraints
    if scope == "pullrequests":
        if repoSlug is None:
            latency = int((time.time() - t0) * 1000)
            _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "repoSlug"})
            return _err("VALIDATION_ERROR", "repoSlug is required when scope='pullrequests'.", field="repoSlug")
    if scope == "code":
        if query is None or (isinstance(query, str) and len(query) == 0):
            latency = int((time.time() - t0) * 1000)
            _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "query"})
            return _err("VALIDATION_ERROR", "query is required and must be non-empty when scope='code'.", field="query")

    # Cursor semantics
    cursor_in = cursor
    if cursor_in is not None and not isinstance(cursor_in, str):
        latency = int((time.time() - t0) * 1000)
        rl = _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "cursor"})
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.", field="cursor")
    if scope == "code" and cursor_in is not None:
        # must be positive integer encoded as string
        try:
            page_n = int(cursor_in)
        except Exception:
            latency = int((time.time() - t0) * 1000)
            _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "cursor"})
            return _err("VALIDATION_ERROR", "For code search, cursor must be a positive integer page number encoded as string.", field="cursor")
        if page_n <= 0:
            latency = int((time.time() - t0) * 1000)
            _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "cursor"})
            return _err("VALIDATION_ERROR", "For code search, cursor must be a positive integer page number encoded as string.", field="cursor")

    # Rate check / log start
    latency = int((time.time() - t0) * 1000)
    rl = _rate_check_and_log(endpoint, "STARTED", latency, {"workspaceSlug": workspaceSlug, "scope": scope})
    if rl:
        return rl

    workspaces = _load("workspaces.json")
    repos = _load("repositories.json")
    prs = _load("pull_requests.json")
    searches = _load("search_requests.json")

    ws = None
    for w in workspaces:
        if w.get("slug") == workspaceSlug:
            ws = w
            break
    if not ws or ws.get("status") == "revoked":
        latency = int((time.time() - t0) * 1000)
        _rate_check_and_log(endpoint, "NOT_FOUND", latency, {"workspaceSlug": workspaceSlug})
        return _err("NOT_FOUND", "Workspace not found or access revoked.", workspaceSlug=workspaceSlug)

    repo = None
    if repoSlug is not None:
        for r in repos:
            if r.get("workspace_id") == ws.get("id") and r.get("slug") == repoSlug:
                repo = r
                break
        if not repo or repo.get("status") == "deleted":
            latency = int((time.time() - t0) * 1000)
            _rate_check_and_log(endpoint, "NOT_FOUND", latency, {"repoSlug": repoSlug})
            return _err("NOT_FOUND", "Repository not found.", repoSlug=repoSlug)

    # Application constraint: repo workspace must match
    if repo is not None and repo.get("workspace_id") != ws.get("id"):
        latency = int((time.time() - t0) * 1000)
        _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "repoSlug"})
        return _err("VALIDATION_ERROR", "Repository does not belong to the specified workspace.", field="repoSlug")

    q = (query or "").strip()
    qlow = q.lower()

    def _matches_text(*fields):
        if not q:
            return True
        for f in fields:
            if isinstance(f, str) and qlow in f.lower():
                return True
        return False

    items = []
    if scope in ("repositories", "all"):
        for r in repos:
            if r.get("workspace_id") != ws.get("id"):
                continue
            if r.get("status") != "active":
                continue
            if _matches_text(r.get("name"), r.get("description"), r.get("slug")):
                items.append({"type": "repository", "slug": r.get("slug"), "name": r.get("name"), "description": r.get("description")})
    if scope in ("pullrequests", "all"):
        # if all and repoSlug is absent, search across repos in workspace
        repo_ids = None
        if scope == "pullrequests":
            repo_ids = {repo.get("id")}
        else:
            repo_ids = {r.get("id") for r in repos if r.get("workspace_id") == ws.get("id") and r.get("status") != "deleted"}
        for pr in prs:
            if pr.get("repository_id") not in repo_ids:
                continue
            if pr.get("status") == "deleted":
                continue
            if _matches_text(pr.get("title"), pr.get("description"), pr.get("author_display_name")):
                items.append({"type": "pullrequest", "id": pr.get("bb_pr_id"), "title": pr.get("title"), "state": pr.get("state")})
    if scope == "commits":
        # No commit collection in schema; return empty but still create a search request row.
        items = []
    if scope == "code":
        # No code index in schema. Preserve cursor semantics by paging empty results.
        items = []

    # Pagination
    cursor_out = None
    start_idx = 0
    if cursor_in:
        # opaque cursor: interpret as last item's stable key for this scope
        # We implement as "offset:<n>" for all non-code, and "page:<n>" for code to preserve semantics.
        if scope == "code":
            try:
                page_n = int(cursor_in)
            except Exception:
                page_n = 1
            start_idx = (page_n - 1) * limit_i
        else:
            if cursor_in.startswith("offset:"):
                try:
                    start_idx = int(cursor_in.split(":", 1)[1])
                except Exception:
                    start_idx = 0
            else:
                # treat unknown as 0
                start_idx = 0

    page = items[start_idx:start_idx + limit_i]
    if start_idx + limit_i < len(items):
        if scope == "code":
            # next page number as string
            next_page = (start_idx // limit_i) + 2
            cursor_out = str(next_page)
        else:
            cursor_out = f"offset:{start_idx + limit_i}"

    now = _now()
    # Create search_requests row (queued->running->succeeded as a single synchronous operation)
    sr = {
        "id": _new_id("srch"),
        "workspace_id": ws.get("id"),
        "repository_id": (repo.get("id") if repo is not None else None),
        "scope": scope,
        "query": (query if query is not None else None),
        "limit": int(limit_i),
        "cursor_in": cursor_in,
        "cursor_out": cursor_out,
        "result_items": page,
        "status": "succeeded",
        "error_message": None,
        "executed_at": now,
        "created_at": now,
        "updated_at": now,
    }
    searches.append(sr)
    _save("search_requests.json", searches)

    latency = int((time.time() - t0) * 1000)
    _rate_check_and_log(endpoint, "OK", latency, {"search_request_id": sr["id"], "returned": len(page)})

    return {
        "search_request": sr,
        "items": page,
        "meta": {
            "limit": limit_i,
            "cursor": cursor_out,
            "has_more": cursor_out is not None,
            "total": len(items),
        },
    }

def get_me(includeScopes=None, includeRateLimit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0524000" if __import__("os").path.isdir("./environment_mix/0524000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _ensure_logs():
        try:
            with open(os.path.join(_DB, "request_logs.json"), encoding="utf-8") as f:
                d = json.load(f)
                if isinstance(d, list):
                    return d
        except Exception:
            return []
        return []

    def _save_logs(logs):
        _save("request_logs.json", logs)

    def _rate_check_and_log(endpoint, status, latency_ms, meta=None):
        logs = _ensure_logs()
        now_ts = _now()
        # Basic rate limit: 120 requests / rolling minute
        window_sec = 60
        limit_per_min = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_sec)
        cnt = 0
        for r in logs:
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if dt.replace(tzinfo=None) >= cutoff:
                    cnt += 1
        if cnt >= limit_per_min:
            logs.append(
                {
                    "id": _new_id("req"),
                    "timestamp": now_ts,
                    "endpoint": endpoint,
                    "status": "RATE_LIMIT",
                    "latency_ms": latency_ms,
                    "meta": meta or {},
                }
            )
            _save_logs(logs)
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=limit_per_min)
        logs.append(
            {
                "id": _new_id("req"),
                "timestamp": now_ts,
                "endpoint": endpoint,
                "status": status,
                "latency_ms": latency_ms,
                "meta": meta or {},
            }
        )
        _save_logs(logs)
        return None

    t0 = time.time()
    endpoint = "get_me"

    if includeScopes is None:
        includeScopes = True
    if includeRateLimit is None:
        includeRateLimit = True
    if not isinstance(includeScopes, bool):
        latency = int((time.time() - t0) * 1000)
        rl = _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "includeScopes"})
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "includeScopes must be a boolean when provided.", field="includeScopes")
    if not isinstance(includeRateLimit, bool):
        latency = int((time.time() - t0) * 1000)
        rl = _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "includeRateLimit"})
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "includeRateLimit must be a boolean when provided.", field="includeRateLimit")

    # This integration uses ambient auth; refuse only if no accessible context exists at all.
    workspaces = _load("workspaces.json")
    accessible = [w for w in workspaces if w.get("status") in ("active", "archived")]

    # rate check/log start
    latency = int((time.time() - t0) * 1000)
    rl = _rate_check_and_log(endpoint, "STARTED", latency, {})
    if rl:
        return rl

    if not accessible:
        latency = int((time.time() - t0) * 1000)
        _rate_check_and_log(endpoint, "UNAUTHORIZED", latency, {})
        return _err("UNAUTHORIZED", "No authenticated context available for this integration.")

    identity = {
        "account_id": "local-user",
        "uuid": None,
        "display_name": "Local Integration User",
    }

    out = {"user": identity, "context": {"accessible_workspaces": len(accessible)}}

    if includeScopes:
        out["scopes"] = [
            "workspace:read",
            "repository:read",
            "pullrequest:read",
            "pullrequest:write",
            "comment:write",
            "search:read",
        ]

    if includeRateLimit:
        logs = _ensure_logs()
        window_sec = 60
        limit_per_min = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_sec)
        used = 0
        for r in logs:
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if dt.replace(tzinfo=None) >= cutoff:
                    used += 1
        reset_in = window_sec
        out["rate_limit"] = {
            "limit_per_minute": limit_per_min,
            "used_in_current_window": used,
            "remaining_in_current_window": max(0, limit_per_min - used),
            "window_seconds": window_sec,
            "reset_hint_seconds": reset_in,
        }

    latency = int((time.time() - t0) * 1000)
    _rate_check_and_log(endpoint, "OK", latency, {"workspaces": len(accessible)})

    return out

def update_workspace(workspaceSlug, status=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0524000" if __import__("os").path.isdir("./environment_mix/0524000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _ensure_logs():
        try:
            with open(os.path.join(_DB, "request_logs.json"), encoding="utf-8") as f:
                d = json.load(f)
                if isinstance(d, list):
                    return d
        except Exception:
            return []
        return []

    def _save_logs(logs):
        _save("request_logs.json", logs)

    def _rate_check_and_log(endpoint, status, latency_ms, meta=None):
        logs = _ensure_logs()
        now_ts = _now()
        # Basic rate limit: 120 requests / rolling minute
        window_sec = 60
        limit_per_min = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_sec)
        cnt = 0
        for r in logs:
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if dt.replace(tzinfo=None) >= cutoff:
                    cnt += 1
        if cnt >= limit_per_min:
            logs.append(
                {
                    "id": _new_id("req"),
                    "timestamp": now_ts,
                    "endpoint": endpoint,
                    "status": "RATE_LIMIT",
                    "latency_ms": latency_ms,
                    "meta": meta or {},
                }
            )
            _save_logs(logs)
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=limit_per_min)
        logs.append(
            {
                "id": _new_id("req"),
                "timestamp": now_ts,
                "endpoint": endpoint,
                "status": status,
                "latency_ms": latency_ms,
                "meta": meta or {},
            }
        )
        _save_logs(logs)
        return None

    t0 = time.time()
    endpoint = "update_workspace"

    if not isinstance(workspaceSlug, str) or len(workspaceSlug) < 1:
        latency = int((time.time() - t0) * 1000)
        rl = _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "workspaceSlug"})
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "workspaceSlug must be a non-empty string.", field="workspaceSlug")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "revoked"):
            latency = int((time.time() - t0) * 1000)
            rl = _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "status"})
            if rl:
                return rl
            return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=["active", "archived", "revoked"])

    # rate check/log start
    latency = int((time.time() - t0) * 1000)
    rl = _rate_check_and_log(endpoint, "STARTED", latency, {"workspaceSlug": workspaceSlug})
    if rl:
        return rl

    workspaces = _load("workspaces.json")

    idx = None
    ws = None
    for i, w in enumerate(workspaces):
        if w.get("slug") == workspaceSlug:
            idx = i
            ws = w
            break

    if not ws:
        latency = int((time.time() - t0) * 1000)
        _rate_check_and_log(endpoint, "NOT_FOUND", latency, {"workspaceSlug": workspaceSlug})
        return _err("NOT_FOUND", "Workspace not found.", workspaceSlug=workspaceSlug)

    if ws.get("status") == "revoked":
        latency = int((time.time() - t0) * 1000)
        _rate_check_and_log(endpoint, "NOT_FOUND", latency, {"workspaceSlug": workspaceSlug})
        return _err("NOT_FOUND", "Workspace not found or access revoked.", workspaceSlug=workspaceSlug)

    if status is None:
        latency = int((time.time() - t0) * 1000)
        _rate_check_and_log(endpoint, "VALIDATION_ERROR", latency, {"field": "status"})
        return _err("VALIDATION_ERROR", "status is required for update.", field="status")

    current = ws.get("status")
    transitions = {
        "active": ["archived", "revoked"],
        "archived": ["active", "revoked"],
        "revoked": [],
    }
    allowed = transitions.get(current, [])
    if status == current:
        # idempotent update; still update updated_at
        now = _now()
        ws["updated_at"] = now
        workspaces[idx] = ws
        _save("workspaces.json", workspaces)
        latency = int((time.time() - t0) * 1000)
        _rate_check_and_log(endpoint, "OK_IDEMPOTENT", latency, {"workspace_id": ws.get("id")})
        return {"workspace": ws, "idempotent": True}

    if status not in allowed:
        latency = int((time.time() - t0) * 1000)
        _rate_check_and_log(endpoint, "INVALID_TRANSITION", latency, {"from": current, "to": status})
        return _err("INVALID_TRANSITION", "Illegal workspace status transition.", from_status=current, to_status=status)

    now = _now()
    ws["status"] = status
    ws["updated_at"] = now
    # touch synced_at? no; lifecycle update is local
    workspaces[idx] = ws
    _save("workspaces.json", workspaces)

    latency = int((time.time() - t0) * 1000)
    _rate_check_and_log(endpoint, "OK", latency, {"workspace_id": ws.get("id"), "status": status})

    return {"workspace": ws}

def update_repository(workspaceSlug, repoSlug, name=None, description=None, is_private=None, fork_policy=None, status=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0524000" if __import__("os").path.isdir("./environment_mix/0524000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_repository"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_s, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status_s,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta:
            row.update(meta)
        logs.append(row)
        _save("request_logs.json", logs)

    def _limits_ok():
        cfg = _load("service_limits.json")
        if isinstance(cfg, list) and cfg:
            cfg = cfg[0]
        if not isinstance(cfg, dict):
            cfg = {}
        rl = cfg.get("rate_limit") if isinstance(cfg.get("rate_limit"), dict) else {}
        qt = cfg.get("quota") if isinstance(cfg.get("quota"), dict) else {}
        rpm = rl.get("requests_per_minute", 120)
        rpd = qt.get("requests_per_day", 20000)
        if not isinstance(rpm, int) or rpm <= 0:
            rpm = 120
        if not isinstance(rpd, int) or rpd <= 0:
            rpd = 20000

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        win_min = now - datetime.timedelta(minutes=1)
        win_day = now - datetime.timedelta(days=1)
        cmin = 0
        cday = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= win_min:
                cmin += 1
            if ts >= win_day:
                cday += 1
        if cmin >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded", requests_per_minute=rpm)
        if cday >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", requests_per_day=rpd)
        return None

    try:
        if not isinstance(workspaceSlug, str) or len(workspaceSlug.strip()) < 1:
            e = _err("VALIDATION_ERROR", "workspaceSlug must be a non-empty string", workspaceSlug=workspaceSlug)
            _log("error", error=e["error"])
            return e
        if not isinstance(repoSlug, str) or len(repoSlug.strip()) < 1:
            e = _err("VALIDATION_ERROR", "repoSlug must be a non-empty string", repoSlug=repoSlug)
            _log("error", error=e["error"])
            return e
        if name is not None and (not isinstance(name, str) or not name.strip()):
            e = _err("VALIDATION_ERROR", "name must be a non-empty string when provided", name=name)
            _log("error", error=e["error"])
            return e
        if description is not None and not isinstance(description, str):
            e = _err("VALIDATION_ERROR", "description must be a string when provided", description=description)
            _log("error", error=e["error"])
            return e
        if is_private is not None and not isinstance(is_private, bool):
            e = _err("VALIDATION_ERROR", "is_private must be a boolean when provided", is_private=is_private)
            _log("error", error=e["error"])
            return e
        if fork_policy is not None:
            if not isinstance(fork_policy, str) or fork_policy not in ("allow_forks", "no_forks", "allow_forks_no_public"):
                e = _err("VALIDATION_ERROR", "fork_policy must be one of allow_forks, no_forks, allow_forks_no_public", fork_policy=fork_policy)
                _log("error", error=e["error"])
                return e
        if status is not None:
            if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
                e = _err("VALIDATION_ERROR", "status must be one of active, archived, deleted", status=status)
                _log("error", error=e["error"])
                return e

        lim = _limits_ok()
        if lim:
            _log("error", error=lim["error"])
            return lim

        wslug = workspaceSlug.strip()
        rslug = repoSlug.strip()

        workspaces = _load("workspaces.json")
        if isinstance(workspaces, dict) and isinstance(workspaces.get("rows"), list):
            workspaces = workspaces["rows"]
        if not isinstance(workspaces, list):
            workspaces = []

        ws = None
        for w in workspaces:
            if isinstance(w, dict) and w.get("slug") == wslug and w.get("status") != "revoked":
                ws = w
                break
        if not ws:
            e = _err("NOT_FOUND", "Workspace not found", workspaceSlug=wslug)
            _log("error", error=e["error"])
            return e

        repos = _load("repositories.json")
        if isinstance(repos, dict) and isinstance(repos.get("rows"), list):
            repos = repos["rows"]
        if not isinstance(repos, list):
            repos = []

        idx = None
        repo = None
        for i, r in enumerate(repos):
            if isinstance(r, dict) and r.get("workspace_id") == ws.get("id") and r.get("slug") == rslug:
                idx = i
                repo = r
                break
        if repo is None:
            # fallback reconcile
            for i, r in enumerate(repos):
                if not isinstance(r, dict) or r.get("slug") != rslug:
                    continue
                wsid = r.get("workspace_id")
                if not isinstance(wsid, str):
                    continue
                for w in workspaces:
                    if isinstance(w, dict) and w.get("id") == wsid and w.get("slug") == wslug and w.get("status") != "revoked":
                        idx = i
                        repo = r
                        ws = w
                        break
                if repo:
                    break

        if repo is None:
            e = _err("NOT_FOUND", "Repository not found", workspaceSlug=wslug, repoSlug=rslug)
