        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_s, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status_s,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta:
            row.update(meta)
        logs.append(row)
        _save("request_logs.json", logs)

    def _limits_ok():
        cfg = _load("service_limits.json")
        if isinstance(cfg, list) and cfg:
            cfg = cfg[0]
        if not isinstance(cfg, dict):
            cfg = {}
        rl = cfg.get("rate_limit") if isinstance(cfg.get("rate_limit"), dict) else {}
        qt = cfg.get("quota") if isinstance(cfg.get("quota"), dict) else {}
        rpm = rl.get("requests_per_minute", 120)
        rpd = qt.get("requests_per_day", 20000)
        if not isinstance(rpm, int) or rpm <= 0:
            rpm = 120
        if not isinstance(rpd, int) or rpd <= 0:
            rpd = 20000

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        win_min = now - datetime.timedelta(minutes=1)
        win_day = now - datetime.timedelta(days=1)
        cmin = 0
        cday = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= win_min:
                cmin += 1
            if ts >= win_day:
                cday += 1
        if cmin >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded", requests_per_minute=rpm)
        if cday >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", requests_per_day=rpd)
        return None

    try:
        if not isinstance(workspaceSlug, str) or len(workspaceSlug.strip()) < 1:
            e = _err("VALIDATION_ERROR", "workspaceSlug must be a non-empty string", workspaceSlug=workspaceSlug)
            _log("error", error=e["error"])
            return e
        if not isinstance(repoSlug, str) or len(repoSlug.strip()) < 1:
            e = _err("VALIDATION_ERROR", "repoSlug must be a non-empty string", repoSlug=repoSlug)
            _log("error", error=e["error"])
            return e
        if not isinstance(prId, int) or prId <= 0:
            e = _err("VALIDATION_ERROR", "prId must be a positive integer", prId=prId)
            _log("error", error=e["error"])
            return e
        if title is not None and (not isinstance(title, str) or not title.strip()):
            e = _err("VALIDATION_ERROR", "title must be a non-empty string when provided", title=title)
            _log("error", error=e["error"])
            return e
        if description is not None and not isinstance(description, str):
            e = _err("VALIDATION_ERROR", "description must be a string when provided", description=description)
            _log("error", error=e["error"])
            return e
        if closeSourceBranch is not None and not isinstance(closeSourceBranch, bool):
            e = _err("VALIDATION_ERROR", "closeSourceBranch must be a boolean when provided", closeSourceBranch=closeSourceBranch)
            _log("error", error=e["error"])
            return e
        if state is not None:
            if not isinstance(state, str) or state not in ("OPEN", "MERGED", "DECLINED", "SUPERSEDED"):
                e = _err("VALIDATION_ERROR", "state must be one of OPEN, MERGED, DECLINED, SUPERSEDED", state=state)
                _log("error", error=e["error"])
                return e

        lim = _limits_ok()
        if lim:
            _log("error", error=lim["error"])
            return lim

        wslug = workspaceSlug.strip()
        rslug = repoSlug.strip()

        workspaces = _load("workspaces.json")
        if isinstance(workspaces, dict) and isinstance(workspaces.get("rows"), list):
            workspaces = workspaces["rows"]
        if not isinstance(workspaces, list):
            workspaces = []

        ws = None
        for w in workspaces:
            if isinstance(w, dict) and w.get("slug") == wslug and w.get("status") != "revoked":
                ws = w
                break
        if not ws:
            e = _err("NOT_FOUND", "Workspace not found", workspaceSlug=wslug)
            _log("error", error=e["error"])
            return e

        repos = _load("repositories.json")
        if isinstance(repos, dict) and isinstance(repos.get("rows"), list):
            repos = repos["rows"]
        if not isinstance(repos, list):
            repos = []

        repo = None
        for r in repos:
            if isinstance(r, dict) and r.get("workspace_id") == ws.get("id") and r.get("slug") == rslug:
                repo = r
                break
        if not repo:
            for r in repos:
                if not isinstance(r, dict) or r.get("slug") != rslug:
                    continue
                wsid = r.get("workspace_id")
                if not isinstance(wsid, str):
                    continue
                for w in workspaces:
                    if isinstance(w, dict) and w.get("id") == wsid and w.get("slug") == wslug and w.get("status") != "revoked":
                        repo = r
                        ws = w
                        break
                if repo:
                    break

        if not repo or repo.get("status") == "deleted":
            e = _err("NOT_FOUND", "Repository not found", workspaceSlug=wslug, repoSlug=rslug)
            _log("error", error=e["error"])
            return e

        prs = _load("pull_requests.json")
        if isinstance(prs, dict) and isinstance(prs.get("rows"), list):
            prs = prs["rows"]
        if not isinstance(prs, list):
            prs = []

        idx = None
        pr = None
        for i, row in enumerate(prs):
            if not isinstance(row, dict):
                continue
            if row.get("repository_id") == repo.get("id") and row.get("bb_pr_id") == prId and row.get("status") != "deleted":
                idx = i
                pr = row
                break
        if pr is None:
            e = _err("NOT_FOUND", "Pull request not found", workspaceSlug=wslug, repoSlug=rslug, prId=prId)
            _log("error", error=e["error"])
            return e

        # terminal state cannot change
        if pr.get("state") in ("MERGED", "DECLINED", "SUPERSEDED"):
            if state is not None and state != pr.get("state"):
                e = _err("INVALID_TRANSITION", f"Pull request in terminal state {pr.get('state')} cannot be changed", current=pr.get("state"), desired=state)
                _log("error", error=e["error"])
                return e

        # transition rules
        if state is not None and state != pr.get("state"):
            allowed = {"OPEN": ("MERGED", "DECLINED", "SUPERSEDED"), "MERGED": (), "DECLINED": (), "SUPERSEDED": ()}
            cur = pr.get("state")
            if state not in allowed.get(cur, ()):
                e = _err("INVALID_TRANSITION", f"Illegal state transition {cur} -> {state}", current=cur, desired=state)
                _log("error", error=e["error"])
                return e

        changed = False
        if title is not None and title != pr.get("title"):
            pr["title"] = title
            changed = True
        if description is not None and description != pr.get("description"):
            pr["description"] = description
            changed = True
        if closeSourceBranch is not None and closeSourceBranch != pr.get("close_source_branch"):
            pr["close_source_branch"] = closeSourceBranch
            changed = True
        if state is not None and state != pr.get("state"):
            pr["state"] = state
            if state == "MERGED":
                pr["merged_on"] = _now_iso()
            changed = True

        if not changed:
            e = _err("CONFLICT", "No changes requested")
            _log("error", error=e["error"])
            return e

        now = _now_iso()
        pr["updated_on"] = now
        pr["updated_at"] = now
        prs[idx] = pr
        _save("pull_requests.json", prs)

        out = {"pull_request": pr, "repository": {"id": repo.get("id"), "slug": repo.get("slug")}, "workspace": {"id": ws.get("id"), "slug": ws.get("slug")}}
        _log("ok", workspace_id=ws.get("id"), repository_id=repo.get("id"), pull_request_id=pr.get("id"))
        return out
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Request failed", detail=str(ex))
        _log("error", error=e["error"])
        return e

